	array(
		'question_text'  => 'A client joins from a parked car outside work. Coworkers repeatedly walk past, and the client becomes hesitant when sensitive topics arise. What is the best response?',
		'option_a'       => 'Continue without addressing privacy because the client selected the location.',
		'option_b'       => 'Discuss the privacy concern, assess whether the client can speak freely, and relocate, modify, or reschedule the session as clinically appropriate.',
