	array(
		'question_text'  => 'Which plan most completely supports telehealth emergency response and continuity?',
		'option_a'       => "The client's home address and instructions to call 911.",
		'option_b'       => 'The name of one emergency contact.',
		'option_c'       => 'A national crisis-line number only.',
